String money(num n)=>NumberFormat.currency(locale:'en_IN',symbol:'₹',decimalDigits:0).format(n);
IconData iconFor(String s){final x=s.toLowerCase();if(x.contains('phone'))return Icons.smartphone;if(x.contains('laptop'))return Icons.laptop;if(x.contains('television'))return Icons.tv;if(x.contains('refrigerator'))return Icons.kitchen;if(x.contains('air conditioner'))return Icons.ac_unit;if(x.contains('washing'))return Icons.local_laundry_service;if(x.contains('audio'))return Icons.headphones;if(x.contains('camera'))return Icons.camera_alt;if(x.contains('printer'))return Icons.print;if(x.contains('network'))return Icons.router;if(x.contains('storage'))return Icons.storage;if(x.contains('customer'))return Icons.people_alt_outlined;if(x.contains('supplier'))return Icons.local_shipping_outlined;if(x.contains('expense'))return Icons.payments_outlined;if(x.contains('report'))return Icons.insights_outlined;if(x.contains('backup'))return Icons.backup_outlined;if(x.contains('warranty'))return Icons.verified_outlined;if(x.contains('dead'))return Icons.hourglass_empty;if(x.contains('user'))return Icons.manage_accounts_outlined;if(x.contains('notification'))return Icons.notifications_outlined;return Icons.inventory_2_outlined;}
