class _POSPageState extends State<POSPage>{List<Product>products=[];List<Map<String,Object?>>cart=[];String q='',payment='Cash';@override void initState(){super.initState();load();}Future<void>load()async{products=await AppDatabase.instance.products(query:q);if(widget.preselected!=null&&!cart.any((x)=>x['product_id']==widget.preselected!.id))add(widget.preselected!);if(mounted)setState((){});}void add(Product p){final i=cart.indexWhere((x)=>x['product_id']==p.id);if(i>=0)cart[i]['quantity']=(cart[i]['quantity'] as int)+1;else cart.add({'product_id':p.id!,'name':p.name,'price':p.sellingPrice,'quantity':1});setState((){});}double get total=>cart.fold(0,(a,x)=>a+(x['price'] as num)*(x['quantity'] as int));Future<void>checkout()async{try{await AppDatabase.instance.sellCart(cart,payment:payment);if(mounted){await showInvoice(c,total);cart.clear();setState((){});}}catch(e){if(mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(e.toString())));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('New Sale')),body:Padding(padding:const EdgeInsets.all(16),child:LayoutBuilder(builder:(_,b){final split=b.maxWidth>850;final catalog=Column(children:[TextField(onChanged:(v){q=v;load();},decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search or scan SKU / barcode')),const SizedBox(height:10),Expanded(child:GridView.builder(itemCount:products.length,gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:split?3:2,crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:.9),itemBuilder:(_,i)=>InkWell(onTap:products[i].quantity>0?()=>add(products[i]):null,child:ProductCard(products[i]))))]);final checkout=Card(child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Cart',style:TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const Divider(),Expanded(child:cart.isEmpty?const Center(child:Text('Add products to start')):ListView(children:cart.map((x)=>ListTile(title:Text(x['name'] as String),subtitle:Text('${x['quantity']} × ${money(x['price'] as num)}'),trailing:IconButton(onPressed:(){setState(()=>cart.remove(x));},icon:const Icon(Icons.delete_outline)))).toList())),Text(money(total),style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900)),DropdownButtonFormField<String>(value:payment,items:['Cash','UPI','Card','Bank Transfer','Credit'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>payment=v!),decoration:const InputDecoration(labelText:'Payment')),const SizedBox(height:8),SizedBox(width:double.infinity,child:FilledButton(onPressed:cart.isEmpty?null:checkout,child:const Text('Complete Sale')))]));return split?Row(children:[Expanded(flex:3,child:catalog),const SizedBox(width:14),SizedBox(width:360,child:checkout)]):Column(children:[Expanded(child:catalog),const SizedBox(height:8),SizedBox(height:275,width:double.infinity,child:checkout)]);}));}
