Future<void>showInvoice(BuildContext c,double total)async{final doc=pw.Document();doc.addPage(pw.Page(build:(_)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('ElectroMart Electronics',style:pw.TextStyle(fontSize:24,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:16),pw.Text('Invoice · ${DateTime.now()}'),pw.SizedBox(height:16),pw.Text('Total: ${money(total)}'),pw.Text('Payment: Paid'),pw.SizedBox(height:18),pw.Text('Warranty information is stored with the sale.')]));await showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Sale Complete'),content:Text('Invoice total ${money(total)}'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close')),FilledButton.icon(onPressed:()=>Printing.layoutPdf(onLayout:(_)=>doc.save()),icon:const Icon(Icons.print),label:const Text('Print / PDF'))]));}
